def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def download(name, path):
    url = "https://raw.githubusercontent.com/MapleHinata/FidelityFX-SDK/%s/%s" % (COMMIT, name)
    request = urllib.request.Request(url, headers={"User-Agent": "s2fix-build"})
    for attempt in range(5):  # raw.githubusercontent.com resets a connection now and then
        try:
            with urllib.request.urlopen(request, timeout=120) as r, open(path + ".part", "wb") as f:
                f.write(r.read())
            return
        except OSError:
            if attempt == 4:
                raise
            time.sleep(2 * (attempt + 1))


def main():
    if len(sys.argv) != 2:
        print(__doc__.strip().splitlines()[-1])
        return 2
    root = sys.argv[1]
    fetched = 0
    for name, want in FILES.items():
        path = os.path.join(root, *name.split("/"))
        if os.path.exists(path) and sha256(path) == want:
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        download(name, path)
        got = sha256(path + ".part")
        if got != want:
            os.remove(path + ".part")
            print("fsr sdk: %s has SHA-256 %s, want %s" % (name, got, want))
            return 1
        os.replace(path + ".part", path)
        fetched += 1
    print("fsr sdk: %d files fetched, %d already there" % (fetched, len(FILES) - fetched))
    return 0


if __name__ == "__main__":
    sys.exit(main())
